interface Calculator {
    int compute(int a, int b);
}

public class TargetTyping {
    public static void main(String[] args) {
        Calculator adder = (a, b) -> a + b;
        java.util.function.BinaryOperator<Integer> boxedAdder = (a, b) -> a + b;

        System.out.println(adder.compute(3, 4));         // 7
        System.out.println(boxedAdder.apply(3, 4));      // 7
    }
}

import java.util.function.Function;
import java.util.function.Consumer;
import java.util.function.Supplier;
import java.util.ArrayList;
import java.util.List;

public class MethodReferences {
    public static void main(String[] args) {
        // 1. static method reference
        Function<String, Integer> parse = Integer::parseInt;
        System.out.println(parse.apply("42"));            // 42

        // 2. instance method reference on a particular existing object
        List<String> log = new ArrayList<>();
        Consumer<String> append = log::add;
        append.accept("entry one");
        System.out.println(log);                            // [entry one]

        // 3. instance method reference on an arbitrary object of a type
        Function<String, String> upper = String::toUpperCase;
        System.out.println(upper.apply("hello"));         // HELLO

        // 4. constructor reference
        Supplier<List<String>> newList = ArrayList::new;
        System.out.println(newList.get());                 // []
    }
}

import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

public class CaptureRules {
    public static void main(String[] args) {
        int threshold = 10;                         // never reassigned -- effectively final
        java.util.function.Predicate<Integer> aboveThreshold = n -> n > threshold;  // OK to capture
        System.out.println(aboveThreshold.test(15)); // true

        // int total = 0;
        // List.of(1, 2, 3).forEach(n -> total += n);
        // does NOT compile: total is reassigned inside the lambda, so it isn't effectively final

        AtomicInteger runningTotal = new AtomicInteger(0);  // the REFERENCE is effectively final
        List.of(1, 2, 3).forEach(n -> runningTotal.addAndGet(n));  // mutating the OBJECT is fine
        System.out.println(runningTotal.get());      // 6
    }
}

