import java.util.List;
import java.util.stream.Collectors;

public class FullPipeline {
    public static void main(String[] args) {
        List<String> words = List.of("pear", "fig", "kiwi", "plum", "date", "apple");

        List<String> result = words.stream()
            .filter(w -> w.length() > 3)
            .map(String::toUpperCase)
            .sorted()
            .collect(Collectors.toList());

        System.out.println(result);   // [APPLE, DATE, KIWI, PEAR, PLUM]
    }
}

import java.util.List;

public class LazinessDemo {
    public static void main(String[] args) {
        List<String> names = List.of("amy", "ben", "cara");

        System.out.println("building pipeline with no terminal operation...");
        names.stream()
            .map(n -> {
                System.out.println("mapping " + n);
                return n.toUpperCase();
            });
        System.out.println("...nothing printed above this line from map()");

        System.out.println("now adding a terminal operation:");
        long count = names.stream()
            .map(n -> {
                System.out.println("mapping " + n);
                return n.toUpperCase();
            })
            .count();
        System.out.println("count = " + count);
    }
}

import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

public class ReduceVsCollect {
    public static void main(String[] args) {
        List<String> words = List.of("pear", "fig", "kiwi", "plum", "date");

        int totalLength = words.stream()
            .map(String::length)
            .reduce(0, Integer::sum);
        System.out.println("total length: " + totalLength);   // 4+3+4+4+4 = 19

        Map<Integer, List<String>> byLength = words.stream()
            .collect(Collectors.groupingBy(String::length));
        System.out.println(byLength);   // {3=[fig], 4=[pear, kiwi, plum, date]}
    }
}

