import java.util.Optional;
import java.util.Map;

public class UserLookup {
    private static final Map<Integer, String> USERS = Map.of(1, "Amy", 2, "Ben");

    static Optional<String> findNameById(int id) {
        return Optional.ofNullable(USERS.get(id));   // Map.get returns null if absent
    }

    public static void main(String[] args) {
        String greeting = findNameById(1)
            .map(name -> "Hello, " + name + "!")
            .orElse("Hello, stranger!");
        System.out.println(greeting);                 // Hello, Amy!

        String missing = findNameById(99)
            .map(name -> "Hello, " + name + "!")
            .orElse("Hello, stranger!");
        System.out.println(missing);                   // Hello, stranger!
    }
}

import java.util.Optional;

public class EagerVsLazyDefault {
    static String expensiveDefault() {
        System.out.println("computing expensive default...");
        return "default-value";
    }

    public static void main(String[] args) {
        Optional<String> present = Optional.of("actual-value");

        System.out.println("using orElse:");
        String a = present.orElse(expensiveDefault());     // expensiveDefault() runs anyway!
        System.out.println("got: " + a);

        System.out.println("using orElseGet:");
        String b = present.orElseGet(EagerVsLazyDefault::expensiveDefault);  // never actually called
        System.out.println("got: " + b);
    }
}

