import java.util.Optional;
import java.util.Map;
import java.util.NoSuchElementException;

public class DiscountApplier {
    private static final Map<String, Double> CODES = Map.of("SAVE10", 0.10, "SAVE20", 0.20);

    static double getDiscountRate(String code) {
        Optional<Double> rate = Optional.ofNullable(CODES.get(code));
        return rate.orElseThrow(() ->
            new NoSuchElementException("Unknown discount code: " + code));
    }

    public static void main(String[] args) {
        System.out.println(getDiscountRate("SAVE10"));
        try {
            System.out.println(getDiscountRate("EXPIRED"));
        } catch (NoSuchElementException e) {
            System.out.println("Could not apply discount: " + e.getMessage());
        }
    }
}

